  #legend .t { font-weight:600; font-size:12.5px; margin-bottom:2px; }
  #legend .li { display:flex; align-items:center; gap:9px; color:var(--ink-2); }
  #basemap { right:60px; top:16px; padding:3px; display:flex; gap:2px; }
