  #basemap button.on, .seg button.on { background:var(--ink); color:var(--s1); }
  .seg { display:inline-flex; padding:3px; gap:2px; border:1px solid var(--line-2); border-radius:11px; background:var(--s1); }
  .leaflet-top.leaflet-right { top:6px; right:6px; }

  /* projection timeline (Planet-style) */
  #timeline { left:50%; bottom:22px; transform:translateX(-50%); display:flex; align-items:center; gap:16px; padding:10px 18px 10px 10px; }
  #mapBox.has-card #timeline { left:calc((100% - 440px) / 2); }
  #mapBox.has-card .leaflet-top.leaflet-right, #mapBox.has-card #basemap { margin-right:430px; }
  #bPlay { width:40px; height:40px; border-radius:50%; border:0; background:var(--ink); color:var(--s1); cursor:pointer; display:grid; place-items:center; flex:none; transition:transform .12s var(--ease); }
  #bPlay:hover { transform:scale(1.06); }
  #bPlay svg { display:block; }
  .stops { position:relative; display:grid; grid-template-columns:repeat(3, 1fr); width:400px; }
  .rail { position:absolute; top:7px; left:16.666%; right:16.666%; height:2px; background:var(--line-2); border-radius:1px; }
  .rail i { position:absolute; inset:0 auto 0 0; background:var(--ink); border-radius:1px; }
  .stops button { position:relative; background:none; border:0; padding:22px 4px 0; cursor:pointer; color:var(--ink-3); text-align:center; line-height:1.25; }
  .stops button::before { content:''; position:absolute; top:2px; left:50%; width:12px; height:12px; margin-left:-6px; border-radius:50%; background:var(--s1); border:2px solid var(--line-2); transition:all .2s var(--ease); }
  .stops button.past::before { border-color:var(--ink); }
  .stops button.on::before { background:var(--ink); border-color:var(--ink); box-shadow:0 0 0 4px rgba(236,238,230,.15); }
  .stops button.on, .stops button:hover { color:var(--ink); }
  .stops b { display:block; font:500 13px var(--mono); }
  .stops span { display:block; font-size:11px; }

  /* floating detail card */
  .card-float { position:absolute; z-index:650; top:16px; right:16px; bottom:16px; width:410px; overflow:auto; background:var(--s1); border:1px solid var(--line); border-radius:16px; box-shadow:var(--shadow); padding:24px 24px 0; animation:slidein .28s var(--ease) both; }
  @keyframes slidein { from { opacity:0; transform:translateX(16px); } }
  .x { position:absolute; top:14px; right:14px; width:30px; height:30px; border-radius:50%; border:0; background:var(--s2); cursor:pointer; font-size:16px; line-height:1; color:var(--ink-2); }
  .x:hover { background:var(--s3); color:var(--ink); }

  /* segment pieces */
  .kp { font:400 46px/0.95 var(--serif); letter-spacing:-.01em; }
  .card-float .kp { font-size:38px; }
  .km { font:12.5px var(--mono); color:var(--ink-2); margin-top:8px; }
  .chip { display:inline-flex; align-items:center; gap:6px; font:600 12px/1 var(--sans); padding:6px 10px; border-radius:999px; white-space:nowrap; }
  .chip .led { width:7px; height:7px; border-radius:50%; background:currentColor; }
  .gauge { margin-top:22px; }
  .gauge .row1 { display:flex; align-items:baseline; justify-content:space-between; gap:12px; flex-wrap:wrap; }
  .gauge .big { font:500 46px/1 var(--mono); letter-spacing:-.04em; white-space:nowrap; }
  .gauge .big small { font-size:14px; color:var(--ink-3); letter-spacing:0; }
  .track { position:relative; height:8px; margin-top:14px; display:grid; grid-template-columns:40fr 25fr 35fr; gap:2px; }
  .track span { border-radius:2px; opacity:.3; }
  .track .pin { position:absolute; top:-6px; width:3px; height:20px; background:var(--ink); border-radius:2px; transition:left .35s var(--ease); box-shadow:0 0 0 3px var(--s1); }
  .ticks { position:relative; height:14px; font:10.5px var(--mono); color:var(--ink-3); margin-top:6px; }
  .ticks span { position:absolute; transform:translateX(-50%); } .ticks span:first-child { transform:none; } .ticks span:last-child { transform:translateX(-100%); }
  .note { font-size:13px; color:var(--amber); border-left:2px solid var(--amber); padding:2px 0 2px 10px; margin-top:14px; }
  .explain { margin-top:20px; padding:16px 18px; border-radius:12px; background:var(--s2); font-size:15px; line-height:1.6; }
  .explain .src { margin-top:10px; font-size:12px; color:var(--ink-3); }
  .blk { margin-top:28px; }
  .blk > h3 { font-size:13px; font-weight:600; margin:0 0 10px; }
  .drv { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:5px 12px; align-items:baseline; padding:9px 0; border-bottom:1px solid var(--line); }
  .drv:last-child { border-bottom:0; }
  .drv .l { font-size:14px; }
  .drv .n { font:500 13px var(--mono); }
  .drv .mbar { grid-column:1 / -1; height:3px; }
  .hb { display:grid; grid-template-columns:110px minmax(0,1fr) 44px; gap:12px; align-items:center; padding:4px 0; }
  .hb .lab { color:var(--ink-2); font-size:12.5px; }
  .hb .bar { position:relative; height:12px; background:var(--s2); border-radius:3px; }
  .hb .bar i { position:absolute; inset:0 auto 0 0; border-radius:3px; transition:width .35s var(--ease); }
  .hb .bar b { position:absolute; top:-4px; bottom:-4px; width:2px; background:var(--ink); border-radius:1px; }
  .hb .val { text-align:right; font:500 13px var(--mono); }
  .cap { font-size:12.5px; color:var(--ink-3); margin-top:10px; line-height:1.5; }
  table.kv { width:100%; border-collapse:collapse; font-size:14px; }
  table.kv td { padding:9px 0; border-bottom:1px solid var(--line); vertical-align:baseline; }
  table.kv td:last-child { text-align:right; font:500 13px var(--mono); white-space:nowrap; padding-left:12px; }
  table.kv tr:last-child td { border-bottom:0; }
  .actions { position:sticky; bottom:0; margin:28px -24px 0; padding:16px 24px 20px; background:linear-gradient(to bottom, rgba(16,18,16,0), var(--s1) 16px); border-top:1px solid var(--line); }
  .doc .actions { margin:32px 0 0; padding:20px 0 0; background:none; position:static; }
  .btnrow { display:flex; gap:8px; }
  .btn { flex:1; display:inline-flex; justify-content:center; align-items:center; gap:8px; padding:11px 14px; border-radius:10px; border:1px solid var(--line-2); background:var(--s1); cursor:pointer; font-size:14px; font-weight:500; text-decoration:none; transition:background .14s var(--ease), border-color .14s var(--ease), transform .08s; }
  .btn:hover { background:var(--s2); border-color:var(--ink-3); }
  .btn:active { transform:translateY(1px); }
  .btn.primary { background:var(--ink); color:var(--s1); border-color:var(--ink); }
  .btn.primary:hover { background:#fff; }
  .btn[aria-pressed=true] { color:var(--green); background:rgba(47,158,91,.08); border-color:rgba(47,158,91,.5); }
  .btn.ghost { flex:none; border-color:transparent; background:none; color:var(--ink-2); }
  .btn.ghost:hover { background:var(--s2); }
  .linkrow { display:flex; justify-content:space-between; align-items:center; margin-top:12px; font-size:13.5px; }
  .linkrow a { font-weight:500; text-decoration:none; }
  .linkrow a:hover { text-decoration:underline; text-underline-offset:3px; }
  details.ovr summary { cursor:pointer; font-size:13.5px; color:var(--ink-2); list-style:none; }
  details.ovr summary::-webkit-details-marker { display:none; }
  details.ovr summary::before { content:'+ '; font-family:var(--mono); }
  details.ovr[open] summary::before { content:'– '; }
  .ovrform { display:grid; grid-template-columns:120px minmax(0,1fr) auto; gap:6px; margin-top:10px; }
  .field { background:var(--bg); border:1px solid var(--line-2); border-radius:8px; padding:8px 10px; font-size:13.5px; min-width:0; }
  .field:focus { outline:none; border-color:var(--ink-2); }
  .field.bad { border-color:var(--amber); }
  .err { grid-column:1 / -1; font-size:12.5px; color:var(--amber); }
  .seghead { display:flex; justify-content:space-between; align-items:flex-end; gap:24px; flex-wrap:wrap; }
  .crumbs { display:flex; align-items:center; gap:8px; font-size:13.5px; margin-bottom:22px; }
  .crumbs a { color:var(--ink-2); text-decoration:none; } .crumbs a:hover { color:var(--ink); }
  .pager { display:flex; gap:6px; }

  /* money */
  .money { display:grid; grid-template-columns:380px minmax(0,1fr); gap:56px; align-items:start; margin-top:48px; }
  .controls { position:sticky; top:24px; background:var(--s1); border:1px solid var(--line); border-radius:16px; padding:24px; }
  .controls h3 { margin:0 0 4px; font-size:15px; }
  .sl { padding:14px 0; border-bottom:1px solid var(--line); }
  .sl:last-of-type { border-bottom:0; }
  .sl .top { display:flex; justify-content:space-between; align-items:baseline; gap:10px; font-size:14px; }
  .sl .top b { font:500 14px var(--mono); }
  .sl .tag { font-size:11px; font-weight:600; margin-left:6px; }
  .sl .tag.src { color:var(--green); } .sl .tag.ours { color:var(--amber); }
  input[type=range] { -webkit-appearance:none; appearance:none; width:100%; height:24px; background:transparent; margin:6px 0 0; cursor:pointer; }
  input[type=range]::-webkit-slider-runnable-track { height:3px; border-radius:2px; background:linear-gradient(to right, var(--ink) var(--p,50%), var(--line-2) var(--p,50%)); }
  input[type=range]::-webkit-slider-thumb { -webkit-appearance:none; width:18px; height:18px; margin-top:-7.5px; border-radius:50%; background:var(--ink); border:3px solid var(--s1); box-shadow:0 1px 4px rgba(0,0,0,.15); }
  input[type=range]::-moz-range-track { height:3px; background:var(--line-2); }
  input[type=range]::-moz-range-progress { height:3px; background:var(--ink); }
  input[type=range]::-moz-range-thumb { width:14px; height:14px; border-radius:50%; background:var(--ink); border:3px solid var(--s1); }
  .callout { font-size:13px; line-height:1.55; padding:12px 14px; border-radius:10px; background:var(--s2); color:var(--ink-2); margin:14px 0 4px; }
  .huge { font:500 clamp(44px, 6vw, 76px)/1 var(--mono); letter-spacing:-.05em; margin:8px 0 12px; font-variant-numeric:tabular-nums; }
  .wf { display:grid; grid-template-columns:minmax(0,1.1fr) minmax(0,1fr) 92px; gap:16px; align-items:center; padding:14px 0; border-bottom:1px solid var(--line); }
  .wf .l { font-size:14.5px; } .wf .l small { display:block; font-size:12.5px; color:var(--ink-3); }
  .wf .trk { position:relative; height:14px; }
  .wf .trk i { position:absolute; top:0; bottom:0; border-radius:3px; transition:left .35s var(--ease), width .35s var(--ease); }
  .wf .trk b { position:absolute; left:50%; top:-6px; bottom:-6px; width:1px; background:var(--ink-3); }
  .wf .n { text-align:right; font:500 14px var(--mono); }
  .wf.total { border-bottom:0; border-top:2px solid var(--ink); }
  .wf.grp { padding:20px 0 6px; border-bottom:0; font:500 10.5px/1.2 var(--mono); text-transform:uppercase; letter-spacing:.12em; color:var(--ink-3); display:block; }
  .verdict { border:1px solid var(--line-2); border-left:3px solid var(--green); border-radius:12px; padding:18px 20px; margin-bottom:28px; background:var(--s1); }
  .verdict.warn { border-left-color:var(--amber); }
  .verdict h3 { margin:0 0 6px; font-size:18px; font-weight:600; letter-spacing:-.01em; }
  .verdict p { margin:6px 0 0; font-size:14px; line-height:1.55; color:var(--ink-2); max-width:70ch; }
  .verdict p b { color:var(--ink); font-weight:600; }
  .verdict .dep { font-size:13px; color:var(--ink-3); }
  .wf.total .l { font-weight:600; }
  .scen { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
  .scen button { text-align:left; padding:20px; border-radius:14px; border:1px solid var(--line); background:var(--s1); cursor:pointer; transition:border-color .14s var(--ease), box-shadow .14s var(--ease); }
  .scen button:hover { border-color:var(--line-2); box-shadow:var(--shadow); }
  .scen button.on { border-color:var(--ink); }
  .scen .v { font:500 28px/1.1 var(--mono); letter-spacing:-.03em; margin:6px 0; display:block; }
  .scen small { font-size:13px; color:var(--ink-2); }
  .linkbtn { background:none; border:0; padding:0; color:var(--ink-2); text-decoration:underline; text-underline-offset:3px; cursor:pointer; font-size:13px; }
  .sources { font-size:12.5px; color:var(--ink-3); line-height:1.6; margin-top:40px; max-width:70ch; }

  /* work orders */
  .wo { margin:0 0 14px; padding:14px 16px; border-radius:12px; border:1px solid var(--line-2); border-left:3px solid var(--green); background:var(--s2); }
  .wo.cancelled { border-left-color:var(--ink-3); opacity:.75; }
  .wo .h { display:flex; justify-content:space-between; gap:10px; align-items:baseline; flex-wrap:wrap; }
  .wo .h b { font:500 13px var(--mono); }
  .wo .meta { font-size:12.5px; color:var(--ink-2); margin-top:4px; }
  .wo ol { margin:10px 0 0; padding-left:18px; font-size:13px; line-height:1.5; color:var(--ink-2); }
  .wo ol li { margin-bottom:4px; }
  .wo .row2 { display:flex; gap:14px; margin-top:10px; font-size:12.5px; flex-wrap:wrap; }
  .pri { font:600 11px/1 var(--mono); padding:3px 6px; border-radius:5px; background:var(--red); color:#1a0a08; }
  .pri.P2 { background:var(--amber); } .pri.P3 { background:var(--green); }
  #toast { position:fixed; left:50%; bottom:28px; transform:translateX(-50%) translateY(20px); opacity:0; z-index:2000; background:var(--ink); color:var(--bg); padding:11px 16px; border-radius:10px; font-size:13.5px; font-weight:500; box-shadow:var(--shadow); transition:opacity .2s var(--ease), transform .2s var(--ease); pointer-events:none; max-width:min(560px, calc(100vw - 32px)); }
  #toast.on { opacity:1; transform:translateX(-50%); }

  /* log */
  table.log { width:100%; border-collapse:collapse; font-size:14px; }
  table.log th { text-align:left; font-size:12px; font-weight:600; color:var(--ink-3); padding:0 12px 10px 0; border-bottom:1px solid var(--line-2); }
  table.log td { padding:14px 12px 14px 0; border-bottom:1px solid var(--line); vertical-align:top; }
  table.log td.m { font:13px var(--mono); white-space:nowrap; }
  .empty { padding:56px 0; text-align:center; color:var(--ink-3); font-size:14px; border:1px dashed var(--line-2); border-radius:14px; }

  /* alignment sheet */
  #sheet { padding:12px 24px 10px; }
  .frame #sheet { padding:18px 22px 14px; }
  .sheet-head { display:flex; align-items:center; gap:16px; margin-bottom:8px; min-height:22px; }
  .sheet-head .t { font-size:13px; font-weight:600; }
  #readout { font-size:12.5px; color:var(--ink-2); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  #readout b { font:500 12.5px var(--mono); color:var(--ink); }
  .keys { display:flex; gap:8px; align-items:center; font-size:11.5px; color:var(--ink-3); white-space:nowrap; }
  kbd { font:500 10.5px/1 var(--mono); padding:2px 5px; border:1px solid var(--line-2); border-bottom-width:2px; border-radius:4px; color:var(--ink-2); background:var(--s2); }
  #strip { display:block; width:100%; cursor:crosshair; user-select:none; }
  #strip text { font-family:var(--sans); }
  #strip .grow { transform-box:fill-box; transform-origin:bottom; animation:grow .7s var(--ease) both; }
  @keyframes grow { from { transform:scaleY(0); } }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation:none !important; transition:none !important; }
  }
  @media (max-width: 1100px) {
    .ws-grid { grid-template-columns:320px minmax(0,1fr); }
    .stats { grid-template-columns:repeat(2, minmax(0,1fr)); }
    .ledger { grid-template-columns:repeat(3, minmax(0,1fr)); }
    .cell:nth-child(3) { border-right:0; }
    .cell:nth-child(-n+3) { border-bottom:1px solid var(--line); }
    .money { grid-template-columns:1fr; }
    .controls { position:static; }
    .keys { display:none; }
    .card-float { width:360px; }
  }
  @media (max-width: 860px) {
    body { height:auto; overflow:auto; display:block; }
    header.top { gap:12px; padding:0 16px; position:sticky; top:0; z-index:1000; }
    header .pill { display:none; }
    header .pill.warn { display:inline-flex; font-size:0; padding:5px; } header .pill.warn .led { width:8px; height:8px; }
    #views, .view { position:static; }
    .view.ws { overflow:visible; }
    .doc { padding:32px 16px 72px; }
    .dek { font-size:16px; }
    .cols.c2, .scen { grid-template-columns:1fr; }
    .stats { grid-template-columns:1fr 1fr; gap:20px; }
    .ov-grid { display:flex; flex-direction:column; height:auto; }
    .ledger { grid-template-columns:repeat(2, minmax(0,1fr)); }
    .cell { padding:12px 16px; border-bottom:1px solid var(--line); }
    .cell:nth-child(2n) { border-right:0; }
    .cell .v { font-size:22px; }
    .ws-grid { display:flex; flex-direction:column; height:auto; }
    .ws-map { height:62vh; order:-1; } .ov-grid .ws-map { order:0; }
    .ws-list { border-right:0; padding:20px 16px; }
    .card-float { position:static; width:auto; margin:0; border-radius:0; border-left:0; border-right:0; box-shadow:none; animation:none; }
    .actions { position:static; margin:24px 0 0; padding:16px 0 20px; background:none; }
    #timeline { left:12px; right:12px; transform:none; bottom:12px; padding:8px 12px 8px 8px; }
    .stops { width:auto; flex:1; }
    .stops span { display:none; }
    #legend { top:12px; left:12px; min-width:0; font-size:11.5px; }
    #basemap { top:auto; bottom:92px; right:12px; }
    #sheet { padding:12px 16px; }
    .wf { grid-template-columns:minmax(0,1fr) 80px; } .wf .trk { grid-column:1 / -1; grid-row:2; }
  }
</style>
</head>
<body>
<header class="top">
  <a class="mark" href="#/" aria-label="TerraCorridor overview">
    <svg width="22" height="22" viewBox="0 0 22 22" aria-hidden="true"><path d="M2 16 C6 16 7 6 11 6 S16 15 20 13" fill="none" stroke="#eceee6" stroke-width="1.6"/><circle cx="2" cy="16" r="2" fill="#eceee6"/><circle cx="11" cy="6" r="2.2" fill="#f2a93b"/><circle cx="20" cy="13" r="2" fill="#eceee6"/></svg>
    <span>Terra<em>Corridor</em></span>
  </a>
  <nav class="pages" id="nav" aria-label="Pages">
    <a href="#/" data-p="overview">Overview</a>
    <a href="#/triage" data-p="triage">Triage</a>
    <a href="#/money" data-p="money">Money</a>
    <a href="#/build" data-p="build">Build</a>
    <a href="#/log" data-p="log">Work orders <span class="count" id="logCount" data-n="0">0</span></a>
  </nav>
  <span class="spacer"></span>
  <span class="pill warn" id="synthBadge" hidden><span class="led"></span>Synthetic demo data</span>
  <span class="pill live" id="liveBadge" hidden><span class="led"></span>Live from n8n</span>
  <span class="pill" id="genAt"></span>
</header>

<div id="views">
  <!-- OVERVIEW -->
  <section class="view ws" id="view-overview" hidden>
    <div class="ov-grid" id="ovGrid">
      <section class="ledger" id="ovLedger" aria-label="Climate summary"></section>
      <div class="hint" id="ovHint">
        <span><b>How to read this:</b> the line is a 169 km pipeline, coloured by its worst natural hazard: ground failure (landslide, washout, frost heave), river crossings, wildfire weather and drought. Blue dots are river crossings.
        <span class="k" style="color:var(--red)">Red</span> = send a crew, <span class="k" style="color:var(--amber)">amber</span> = watch, <span class="k" style="color:var(--green)">green</span> = inspect less.
        Press <b>&#9654;</b> on the map to watch climate change shift it from today to 2036. Hover any number for what it means.</span>
        <button class="linkbtn" id="bHint">Got it</button>
      </div>
      <div class="ws-map"><div class="map-slot" data-map></div></div>
      <div class="ws-strip ov-strip" data-strip="0.55" data-lanes="climate" data-annot="1"></div>
    </div>
  </section>

  <!-- TRIAGE -->
  <section class="view ws" id="view-triage" hidden>
    <div class="ws-grid">
      <div class="ws-list" id="triageList"></div>
      <div class="ws-map"><div class="map-slot" data-map></div><div class="card-float" id="triageCard" hidden></div></div>
      <div class="ws-strip" data-strip="1"></div>
    </div>
  </section>

  <!-- SEGMENT -->
  <section class="view" id="view-segment" hidden>
    <div class="doc">
      <div id="segHead"></div>
      <div class="frame" style="margin-top:32px"><div data-strip="0.75"></div></div>
      <div id="segBody"></div>
    </div>
  </section>

