<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>window.TC_API = location.origin + location.pathname.replace(/\/map\/?$/, "");</script>
<script>
// TerraCorridor engine. Pure functions, no imports, so the same code runs in
// Node (tests, scripts) and inside an n8n Code node (paste via scripts/build-n8n.js).
// Rules decide. AI only explains. Missing data means "unverified", never "safe".

const DEFAULTS = {
  segmentKm: 1,
  exclusionM: 30,          // CER prescribed area, each side of centreline
  studyStripM: 200,        // land studied beyond the exclusion band, each side
  buildStripM: 60,         // assumption: total width actually leased for panels, outside the exclusion band (both sides combined)
  baselineYears: [1995, 2025],
  horizons: { y5: [2026, 2031], y10: [2026, 2036] },
  wetDayMm: 1,
  extremePct: 0.95,
  soilWetPct: 0.90,
  soilDryPct: 0.10,        // dry-soil day: topsoil below the baseline's 10th percentile
  fireWeather: { tmaxC: 25, rhMinPct: 35, dryMm: 1 },   // provisional fire-weather day: no rain, hot, dry air
  fireDaysFull: 20,        // projected fire-weather days a year that count as full exposure
  peakFlowFullM3s: 200,    // mean annual peak flow (m3/s) that counts as a large river at a crossing
  crossingSize: { river: 1, canal: 0.6, stream: 0.4, drain: 0.3 },
  hazardWeights: {         // each hazard is scored on its own; the segment's level is its worst hazard
    drought: { drySoil: 0.6, drySpell: 0.4 },
    wildfire: { change: 0.5, level: 0.4, fuel: 0.1 },
    crossing: { size: 0.4, rain: 0.35, flow: 0.25 },
  },
  weights: { rain: 0.35, freezeThaw: 0.20, saturation: 0.15, vegetation: 0.20, slope: 0.10 },
  tiers: { amber: 40, red: 65 },
  ndviDropFull: 0.10,      // NDVI drop over 5 years that counts as full vegetation loss
  slopeFullPct: 15,
  buildMaxSlopePct: 10,
  workOrderDueDays: { P1: 14, P2: 60, P3: 180 },  // assumption: red within 2 weeks, amber within 2 months
  // Money (assumptions unless noted; all editable on the dashboard)
  money: {
    baseFailRatePerKmYr: 5e-5,  // assumption: rough natural-force rate, see docs
    riskMultiplierMax: 10,      // score 100 => 10x base rate (assumption)
    costOfFailure: 430000,      // sourced: avg ground-movement failure damage (AWWA)
    mitigationEffectiveness: 0.75,
    workOrderCost: 3000,           // assumption: one targeted field inspection of a flagged km
    inspectionCostPerKm: 500,      // assumption: routine geohazard inspection, per km per visit
    greenInspectEveryYrs: 3,       // assumption: green km move from yearly to every 3 years
    programCostYr: 50000,          // assumption: what an operator pays for TerraCorridor per corridor
    acresPerMW: 6,
    performanceRatio: 0.8,
    leaseRatePerAcreYr: 400,       // assumption: conservative solar land lease, per acre per year
    partnerShare: 0.5,
    gridEmissionFactor: 0.5,    // tCO2 per MWh, enter your grid's figure
  },
};

const R_EARTH = 6371000;
const toRad = (d) => (d * Math.PI) / 180;
const toDeg = (r) => (r * 180) / Math.PI;
const clamp01 = (x) => Math.max(0, Math.min(1, x));
const round = (x, n = 2) => (x == null || Number.isNaN(x) ? null : Math.round(x * 10 ** n) / 10 ** n);

function haversine(a, b) {
  const [lon1, lat1] = a, [lon2, lat2] = b;
  const dLat = toRad(lat2 - lat1), dLon = toRad(lon2 - lon1);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * R_EARTH * Math.asin(Math.sqrt(h));
}

function bearing(a, b) {
  const [lon1, lat1] = a.map(toRad), [lon2, lat2] = b.map(toRad);
  const y = Math.sin(lon2 - lon1) * Math.cos(lat2);
  const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(lon2 - lon1);
  return Math.atan2(y, x);
}

// Point at distance d (m) along bearing brng (rad) from p [lon, lat]
function offset(p, d, brng) {
  const lat1 = toRad(p[1]), lon1 = toRad(p[0]), dr = d / R_EARTH;
  const lat2 = Math.asin(Math.sin(lat1) * Math.cos(dr) + Math.cos(lat1) * Math.sin(dr) * Math.cos(brng));
  const lon2 = lon1 + Math.atan2(Math.sin(brng) * Math.sin(dr) * Math.cos(lat1), Math.cos(dr) - Math.sin(lat1) * Math.sin(lat2));
  return [round(toDeg(lon2), 6), round(toDeg(lat2), 6)];
}

function interpolate(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

// Cut a route ([[lon,lat], ...]) into segments of segmentKm.
// Each segment gets: centreline, a study polygon (exclusion band + strip, both sides),
// an exclusion polygon, a midpoint, and two sample points in the middle of each strip.
function segmentRoute(coords, cfg = DEFAULTS) {
  if (!Array.isArray(coords) || coords.length < 2) throw new Error('route needs at least 2 points');
  const segLen = cfg.segmentKm * 1000;
  const pieces = [];
  let current = [coords[0]], acc = 0;
  for (let i = 1; i < coords.length; i++) {
    let a = coords[i - 1];
    const b = coords[i];
    let d = haversine(a, b);
    while (acc + d >= segLen) {
      const t = (segLen - acc) / d;
      const cut = interpolate(a, b, t);
      current.push(cut);
      pieces.push(current);
      current = [cut];
      d -= segLen - acc;
      a = cut;
      acc = 0;
    }
    acc += d;
    current.push(b);
  }
  if (current.length > 1 && acc > segLen * 0.25) pieces.push(current);

  const outer = cfg.exclusionM + cfg.studyStripM;
  return pieces.map((line, i) => {
    const start = line[0], end = line[line.length - 1];
    const brng = bearing(start, end);
    const left = brng - Math.PI / 2, right = brng + Math.PI / 2;
    const mid = line[Math.floor(line.length / 2)] && interpolate(start, end, 0.5);
    const ring = (dist) => [offset(start, dist, left), offset(end, dist, left), offset(end, dist, right), offset(start, dist, right), offset(start, dist, left)];
    let lengthM = 0;
    for (let k = 1; k < line.length; k++) lengthM += haversine(line[k - 1], line[k]);
    return {
      id: `KP${String(i).padStart(3, '0')}`,
      kmFrom: i * cfg.segmentKm,
      kmTo: round(i * cfg.segmentKm + lengthM / 1000, 3),
      lengthM: Math.round(lengthM),
      centreline: line.map((p) => [round(p[0], 6), round(p[1], 6)]),
      mid: [round(mid[0], 6), round(mid[1], 6)],
      studyPolygon: ring(outer),
      exclusionPolygon: ring(cfg.exclusionM),
      samples: [offset(mid, cfg.exclusionM + cfg.studyStripM / 2, left), offset(mid, cfg.exclusionM + cfg.studyStripM / 2, right)],
      studyAreaAcres: round((lengthM * cfg.studyStripM * 2) / 4046.86, 1),
    };
  });
}

function quantile(values, q) {
  const v = values.filter((x) => x != null && !Number.isNaN(x)).sort((a, b) => a - b);
  if (!v.length) return null;
  const pos = (v.length - 1) * q, lo = Math.floor(pos), hi = Math.ceil(pos);
  return v[lo] + (v[hi] - v[lo]) * (pos - lo);
}

function yearsSpanned(times) {
  const ys = new Set(times.map((t) => t.slice(0, 4)));
  return ys.size || 1;
}

// daily: Open-Meteo style { time:[], precipitation_sum:[], temperature_2m_min:[], temperature_2m_max:[], soil_moisture?:[] }
function soilSeries(daily) {
  return daily.soil_moisture_0_to_10cm_mean || daily.soil_moisture_0_to_7cm_mean || daily.soil_moisture || null;
}

function baselineStats(daily, cfg = DEFAULTS) {
  const t = daily.time || [];
  if (!t.length) return null;
  const years = yearsSpanned(t);
  const pr = daily.precipitation_sum || [];
  const wet = pr.filter((x) => x != null && x >= cfg.wetDayMm);
  const extremeMm = quantile(wet, cfg.extremePct);
  const tmin = daily.temperature_2m_min || [], tmax = daily.temperature_2m_max || [];
  const soil = soilSeries(daily);
  const soilWetThreshold = soil ? quantile(soil, cfg.soilWetPct) : null;
  const soilDryThreshold = soil ? quantile(soil, cfg.soilDryPct) : null;
  const rh = rhSeries(daily);
  const counts = countEvents(daily, { extremeMm, soilWetThreshold, soilDryThreshold }, cfg);
  return {
    years,
    extremeMm: round(extremeMm, 1),
    soilWetThreshold: round(soilWetThreshold, 3),
    soilDryThreshold: round(soilDryThreshold, 3),
    extremeDaysPerYr: round(counts.extreme / years, 2),
    freezeThawDaysPerYr: round(counts.freezeThaw / years, 2),
    wetSoilDaysPerYr: soil ? round(counts.wetSoil / years, 2) : null,
    drySoilDaysPerYr: soil ? round(counts.drySoil / years, 2) : null,
    drySpellDays: round(drySpell(daily, cfg), 1),
    fireWeatherDaysPerYr: rh ? round(counts.fire / years, 2) : null,
    annualPrecipMm: round(pr.reduce((s, x) => s + (x || 0), 0) / years, 0),
  };
}

function countEvents(daily, th, cfg = DEFAULTS) {
  const pr = daily.precipitation_sum || [];
  const tmin = daily.temperature_2m_min || [], tmax = daily.temperature_2m_max || [];
  const soil = soilSeries(daily), rh = rhSeries(daily), fw = cfg.fireWeather || DEFAULTS.fireWeather;
  let extreme = 0, freezeThaw = 0, wetSoil = 0, drySoil = 0, fire = 0;
  for (let i = 0; i < (daily.time || []).length; i++) {
    if (th.extremeMm != null && pr[i] != null && pr[i] > th.extremeMm) extreme++;
    if (tmin[i] != null && tmax[i] != null && tmin[i] < 0 && tmax[i] > 0) freezeThaw++;
    if (soil && th.soilWetThreshold != null && soil[i] != null && soil[i] > th.soilWetThreshold) wetSoil++;
    if (soil && th.soilDryThreshold != null && soil[i] != null && soil[i] < th.soilDryThreshold) drySoil++;
    if (rh && rh[i] != null && tmax[i] != null && pr[i] != null && pr[i] < fw.dryMm && tmax[i] >= fw.tmaxC && rh[i] <= fw.rhMinPct) fire++;
  }
  return { extreme, freezeThaw, wetSoil, drySoil, fire };
}

// Daily minimum relative humidity, when the source has it (two of the three climate models do).
function rhSeries(daily) { return hasValues(daily.relative_humidity_2m_min) ? daily.relative_humidity_2m_min : null; }

// Mean over years of each year's longest run of days with less than wetDayMm of rain.
function drySpell(daily, cfg = DEFAULTS) {
  const t = daily.time || [], pr = daily.precipitation_sum || [];
  if (!t.length || !hasValues(pr)) return null;
  const longest = {};
  let run = 0, year = null;
  for (let i = 0; i < t.length; i++) {
    const y = t[i].slice(0, 4);
    if (y !== year) { run = 0; year = y; }
    run = pr[i] != null && pr[i] < cfg.wetDayMm ? run + 1 : 0;
    longest[y] = Math.max(longest[y] || 0, run);
  }
  const v = Object.values(longest);
  return v.reduce((a, x) => a + x, 0) / v.length;
}

// Filter an Open-Meteo daily block to [y0, y1] inclusive.
function sliceYears(daily, y0, y1) {
  const keep = (daily.time || []).map((t) => { const y = +t.slice(0, 4); return y >= y0 && y <= y1; });
  const out = {};
  for (const k of Object.keys(daily)) out[k] = Array.isArray(daily[k]) ? daily[k].filter((_, i) => keep[i]) : daily[k];
  return out;
}

// Open-Meteo Climate API returns one key per model, e.g. precipitation_sum_MRI_AGCM3_2_S.
function splitModels(daily, models) {
  const out = {};
  for (const m of models) {
    const d = { time: daily.time };
    for (const k of Object.keys(daily)) if (k.endsWith('_' + m)) d[k.slice(0, -(m.length + 1))] = daily[k];
    out[m] = d;
  }
  return out;
}

// Projected event frequencies per model for a window.
// Delta method: when the model series also covers the baseline years, each model is compared with
// its OWN historical run (thresholds and counts), which removes model bias. The change ratio is then
// applied to the observed baseline for display. Without model history it falls back to observed thresholds.
function hasValues(arr) { return Array.isArray(arr) && arr.some((x) => x != null && !Number.isNaN(x)); }

function projectedStats(dailyByModel, base, window, cfg = DEFAULTS) {
  const res = {};
  for (const [model, daily] of Object.entries(dailyByModel)) {
    const d = sliceYears(daily, window[0], window[1]);
    if (!d.time || !d.time.length || !hasValues(d.precipitation_sum)) { res[model] = null; continue; }
    const hist = sliceYears(daily, cfg.baselineYears[0], cfg.baselineYears[1]);
    const own = hist.time && hist.time.length >= 3650 && hasValues(hist.precipitation_sum) ? baselineStats(hist, cfg) : null;
    const ref = own || base;
    const years = yearsSpanned(d.time);
    const soilOk = hasValues(soilSeries(d)) && ref.soilWetThreshold != null;
    const dryOk = hasValues(soilSeries(d)) && ref.soilDryThreshold != null;
    const rhOk = hasValues(rhSeries(d)) && ref.fireWeatherDaysPerYr != null;
    const c = countEvents(d, { extremeMm: ref.extremeMm, soilWetThreshold: soilOk ? ref.soilWetThreshold : null, soilDryThreshold: dryOk ? ref.soilDryThreshold : null }, cfg);
    res[model] = {
      extremeDaysPerYr: round(c.extreme / years, 2),
      freezeThawDaysPerYr: round(c.freezeThaw / years, 2),
      wetSoilDaysPerYr: soilOk ? round(c.wetSoil / years, 2) : null,
      drySoilDaysPerYr: dryOk ? round(c.drySoil / years, 2) : null,
      drySpellDays: ref.drySpellDays != null ? round(drySpell(d, cfg), 1) : null,
      fireWeatherDaysPerYr: rhOk ? round(c.fire / years, 2) : null,
      refExtremeDaysPerYr: ref.extremeDaysPerYr,
      refFreezeThawDaysPerYr: ref.freezeThawDaysPerYr,
      refWetSoilDaysPerYr: soilOk ? ref.wetSoilDaysPerYr : null,
      refDrySoilDaysPerYr: dryOk ? ref.drySoilDaysPerYr : null,
      refDrySpellDays: ref.drySpellDays ?? null,
      refFireWeatherDaysPerYr: rhOk ? ref.fireWeatherDaysPerYr : null,
      method: own ? 'delta' : 'observed-threshold',
    };
  }
  return res;
}

// Least-squares slope per year of a monthly NDVI series [{date:'YYYY-MM-DD', ndvi}],
// growing season only (May to Sep). Returns change over the last 5 years (negative = loss).
function ndviTrend(series) {
  const pts = (series || []).filter((p) => p && p.ndvi != null && +p.date.slice(5, 7) >= 5 && +p.date.slice(5, 7) <= 9)
    .map((p) => ({ x: +p.date.slice(0, 4) + (+p.date.slice(5, 7) - 1) / 12, y: p.ndvi }));
  if (pts.length < 6) return null;
  const n = pts.length, mx = pts.reduce((s, p) => s + p.x, 0) / n, my = pts.reduce((s, p) => s + p.y, 0) / n;
  const sxy = pts.reduce((s, p) => s + (p.x - mx) * (p.y - my), 0), sxx = pts.reduce((s, p) => s + (p.x - mx) ** 2, 0);
  const slopePerYr = sxx ? sxy / sxx : 0;
  return { slopePerYr: round(slopePerYr, 4), change5yr: round(slopePerYr * 5, 3), meanNdvi: round(my, 3), n };
}

const ratioFactor = (proj, base) => {
  if (proj == null || base == null) return null;
  if (base === 0) return proj > 0 ? 1 : 0;
  return clamp01(proj / base - 1); // ratio 1 => 0, ratio 2+ => 1
};

function mean(xs) { const v = xs.filter((x) => x != null); return v.length ? v.reduce((s, x) => s + x, 0) / v.length : null; }

// Score one segment for one horizon. Returns tier "unverified" if any core input is missing.
function riskScore(seg, horizonKey, cfg = DEFAULTS, model = null) {
  const base = seg.baseline, proj = seg.projections && seg.projections[horizonKey];
  const missing = [];
  if (!base) missing.push('baseline');
  if (!proj || !Object.values(proj).some(Boolean)) missing.push('projections');
  if (seg.slopePct == null) missing.push('slope');
  if (missing.length) return { score: null, tier: 'unverified', missing, factors: null, drivers: [], agreement: null };

  const models = Object.values(proj).filter(Boolean);
  const ratio = (m, k, refK, baseK) => {
    if (m[k] == null) return null;
    const ref = m[refK] != null ? m[refK] : base[baseK];
    if (ref == null) return null;
    return ref === 0 ? (m[k] > 0 ? 2 : 1) : m[k] / ref;
  };
  const rRain = mean(models.map((m) => ratio(m, 'extremeDaysPerYr', 'refExtremeDaysPerYr', 'extremeDaysPerYr')));
  const rFt = mean(models.map((m) => ratio(m, 'freezeThawDaysPerYr', 'refFreezeThawDaysPerYr', 'freezeThawDaysPerYr')));
  const rWet = mean(models.map((m) => ratio(m, 'wetSoilDaysPerYr', 'refWetSoilDaysPerYr', 'wetSoilDaysPerYr')));
  // Bias-corrected projections in observed units, for display
  const projRain = rRain != null && base.extremeDaysPerYr != null ? rRain * base.extremeDaysPerYr : null;
  const projFt = rFt != null && base.freezeThawDaysPerYr != null ? rFt * base.freezeThawDaysPerYr : null;
  const projWet = rWet != null && base.wetSoilDaysPerYr != null ? rWet * base.wetSoilDaysPerYr : null;

  const factors = {
    rain: rRain == null ? null : clamp01(rRain - 1),
    freezeThaw: rFt == null ? null : clamp01(rFt - 1),
    saturation: rWet == null ? null : clamp01(rWet - 1),
    vegetation: seg.ndvi ? clamp01(-seg.ndvi.change5yr / cfg.ndviDropFull) : null,
    slope: clamp01(seg.slopePct / cfg.slopeFullPct),
  };

  let score;
  if (model && model.coefficients) {
    // Learned logistic regression on the same factors (see ml/train.py). Probability -> 0..100.
    let z = model.intercept || 0;
    for (const [k, w] of Object.entries(model.coefficients)) z += w * (factors[k] ?? 0);
    score = 100 / (1 + Math.exp(-z));
    if (factors.vegetation != null) score = Math.min(100, score + cfg.weights.vegetation * 100 * factors.vegetation * 0.5);
  } else {
    // Hand-set weights. Factors with no data are dropped and the rest re-weighted.
    let wSum = 0, s = 0;
    for (const [k, w] of Object.entries(cfg.weights)) if (factors[k] != null) { s += w * factors[k]; wSum += w; }
    score = wSum ? (100 * s) / wSum : 0;
  }

  // Model agreement on the direction of extreme-rain change.
  const dirs = models.map((m) => Math.sign(ratio(m, 'extremeDaysPerYr', 'refExtremeDaysPerYr', 'extremeDaysPerYr') - 1));
  const up = dirs.filter((d) => d > 0).length, down = dirs.filter((d) => d < 0).length;
  const agree = Math.max(up, down);
  const agreement = models.length < 2 ? 'low' : agree === models.length ? 'high' : agree >= 2 ? 'medium' : 'low';

  const tierOf = (v) => (v >= cfg.tiers.red ? 'red' : v >= cfg.tiers.amber ? 'amber' : 'green');
  const pct = (r) => (r == null ? null : Math.round((r - 1) * 100));
  const drivers = [
    { key: 'rain', label: 'Extreme-rain days', change: pct(rRain), base: base.extremeDaysPerYr, proj: round(projRain, 1), w: cfg.weights.rain * (factors.rain || 0) },
    { key: 'freezeThaw', label: 'Freeze-thaw days', change: pct(rFt), base: base.freezeThawDaysPerYr, proj: round(projFt, 1), w: cfg.weights.freezeThaw * (factors.freezeThaw || 0) },
    { key: 'saturation', label: 'Wet-soil days', change: pct(rWet), base: base.wetSoilDaysPerYr, proj: round(projWet, 1), w: cfg.weights.saturation * (factors.saturation || 0) },
    { key: 'vegetation', label: 'Vegetation change (NDVI, 5 yr)', change: seg.ndvi ? seg.ndvi.change5yr : null, w: cfg.weights.vegetation * (factors.vegetation || 0) },
    { key: 'slope', label: 'Slope', change: seg.slopePct, w: cfg.weights.slope * (factors.slope || 0) },
  ].sort((a, b) => b.w - a.w);

  // Each natural hazard is scored on its own. The segment's level is its WORST hazard, never a blend,
  // so a reader can always see which hazard made a kilometre red.
  const top0 = drivers[0];
  const ground = { key: 'ground', label: 'Ground failure', score: round(score, 1),
    why: top0 && top0.change != null ? (top0.key === 'slope' ? `Slope ${top0.change}%` : top0.key === 'vegetation' ? `Plant cover ${top0.change} NDVI in 5 years` : `${top0.label} ${top0.change > 0 ? '+' : ''}${top0.change}%`) : 'No change from baseline' };
  const list = [ground, crossingHazard(seg, rRain, cfg), wildfireHazard(seg, models, base, cfg, ratio), droughtHazard(models, base, cfg, ratio)]
    .filter((h) => h && h.score != null);
  for (const h of list) h.tier = tierOf(h.score);
  const top = list.reduce((a, h) => (h.score > a.score ? h : a), ground);
  const tier = tierOf(top.score);
  const rainBased = top.key === 'ground' || top.key === 'crossing';
  return {
    score: top.score,
    groundScore: ground.score,
    tier: tier === 'red' && agreement === 'low' && rainBased ? 'red-uncertain' : tier,
    hazard: top.key,
    hazards: Object.fromEntries(list.map((h) => [h.key, h])),
    agreement,
    factors: Object.fromEntries(Object.entries(factors).map(([k, v]) => [k, round(v, 3)])),
    drivers,
    method: model ? 'logistic-regression' : 'weighted-rules',
  };
}

// Weighted mean of the factors that have data; factors with no data are dropped and the rest re-weighted.
function weightedScore(factors, weights) {
  let s = 0, w = 0;
  for (const [k, wt] of Object.entries(weights)) if (factors[k] != null) { s += wt * factors[k]; w += wt; }
  return w ? round((100 * s) / w, 1) : null;
}
const sgn = (x) => (x > 0 ? '+' : '') + x;

// Drought: more dry-soil days and longer dry spells than 1995-2025. Shrinking clay soils crack and settle
// along the trench, and dry land feeds wildfire.
function droughtHazard(models, base, cfg, ratio) {
  const rSoil = mean(models.map((m) => ratio(m, 'drySoilDaysPerYr', 'refDrySoilDaysPerYr', 'drySoilDaysPerYr')));
  const rSpell = mean(models.map((m) => ratio(m, 'drySpellDays', 'refDrySpellDays', 'drySpellDays')));
  const f = { drySoil: rSoil == null ? null : clamp01(rSoil - 1), drySpell: rSpell == null ? null : clamp01(rSpell - 1) };
  const score = weightedScore(f, cfg.hazardWeights.drought);
  if (score == null) return null;
  const pSoil = rSoil == null ? null : Math.round((rSoil - 1) * 100), pSpell = rSpell == null ? null : Math.round((rSpell - 1) * 100);
  const why = pSoil != null && (pSpell == null || Math.abs(pSoil) >= Math.abs(pSpell)) ? `Dry-soil days ${sgn(pSoil)}%` : `Longest dry spell ${sgn(pSpell)}%`;
  return { key: 'drought', label: 'Drought', score, factors: f, why,
    change: { drySoil: pSoil, drySpell: pSpell },
    base: { drySoilDaysPerYr: base.drySoilDaysPerYr ?? null, drySpellDays: base.drySpellDays ?? null },
    proj: { drySoilDaysPerYr: rSoil != null && base.drySoilDaysPerYr != null ? round(rSoil * base.drySoilDaysPerYr, 1) : null,
      drySpellDays: rSpell != null && base.drySpellDays != null ? round(rSpell * base.drySpellDays, 1) : null } };
}

// Wildfire weather: hot, dry, rainless days, how many there will be, and how much vegetation there is to burn.
// Fire threatens valve sites and above-ground equipment, and burn scars make slopes slide.
function wildfireHazard(seg, models, base, cfg, ratio) {
  const rFire = mean(models.map((m) => ratio(m, 'fireWeatherDaysPerYr', 'refFireWeatherDaysPerYr', 'fireWeatherDaysPerYr')));
  if (rFire == null || base.fireWeatherDaysPerYr == null) return null;
  const proj = rFire * base.fireWeatherDaysPerYr;
  const pts = (seg.ndviSeries || []).filter((p) => p.ndvi != null);
  const ndviMean = pts.length ? pts.reduce((a, p) => a + p.ndvi, 0) / pts.length : null;
  // Fire-weather days are few, so ratios jump: full weight only at three times the baseline (+200%).
  const f = { change: clamp01((rFire - 1) / 2), level: clamp01(proj / cfg.fireDaysFull), fuel: ndviMean == null ? null : clamp01((ndviMean - 0.3) / 0.4) };
  const score = weightedScore(f, cfg.hazardWeights.wildfire);
  const ch = Math.round((rFire - 1) * 100);
  return { key: 'wildfire', label: 'Wildfire weather', score, factors: f,
    why: `Fire-weather days ${round(base.fireWeatherDaysPerYr, 1)} to ${round(proj, 1)} a year (${sgn(ch)}%)`,
    change: { fireDays: ch }, base: { fireWeatherDaysPerYr: base.fireWeatherDaysPerYr }, proj: { fireWeatherDaysPerYr: round(proj, 1) },
    fuelNdvi: round(ndviMean, 2) };
}

// River crossing: only where the pipe actually crosses water. Bigger rivers, higher historical peak flow,
// and more projected heavy rain mean more scour and bank erosion at the crossing.
function crossingHazard(seg, rRain, cfg) {
  const xs = seg.crossings || [];
  if (!xs.length) return null;
  const size = Math.max(...xs.map((x) => cfg.crossingSize[x.kind] ?? 0.4));
  const flows = xs.map((x) => x.peakFlowM3s).filter((v) => v != null);
  const peak = flows.length ? Math.max(...flows) : null;
  const f = { size, rain: rRain == null ? null : clamp01(rRain - 1), flow: peak == null ? null : clamp01(peak / cfg.peakFlowFullM3s) };
  const score = weightedScore(f, cfg.hazardWeights.crossing);
  const big = xs.reduce((a, x) => ((cfg.crossingSize[x.kind] ?? 0) > (cfg.crossingSize[a.kind] ?? 0) ? x : a), xs[0]);
  const rainTxt = rRain == null ? '' : `, heavy rain ${sgn(Math.round((rRain - 1) * 100))}%`;
  return { key: 'crossing', label: 'River crossing', score, factors: f,
    why: `Crosses ${big.name || 'a ' + big.kind}${peak != null ? ` (peak flow ${Math.round(peak)} m³/s)` : ''}${rainTxt}`,
    crossings: xs.map((x) => ({ name: x.name || null, kind: x.kind, peakFlowM3s: x.peakFlowM3s ?? null, at: x.at || null })) };
}

// Mean of each year's highest daily river discharge (m3/s), from the Open-Meteo Flood API (GloFAS).
function peakFlow(daily) {
  const t = daily.time || [], q = daily.river_discharge || [];
  if (!hasValues(q)) return null;
  const max = {};
  t.forEach((d, i) => { if (q[i] != null) max[d.slice(0, 4)] = Math.max(max[d.slice(0, 4)] ?? -Infinity, q[i]); });
  const v = Object.values(max);
  return v.length ? round(v.reduce((a, x) => a + x, 0) / v.length, 1) : null;
}

// Where a pipeline segment crosses a mapped waterway. waterways: [{ name, kind, coords: [[lon,lat],...] }].
function findCrossings(segments, waterways) {
  const hit = (p1, p2, p3, p4) => {
    const d = (p4[1] - p3[1]) * (p2[0] - p1[0]) - (p4[0] - p3[0]) * (p2[1] - p1[1]);
    if (!d) return null;
    const ua = ((p4[0] - p3[0]) * (p1[1] - p3[1]) - (p4[1] - p3[1]) * (p1[0] - p3[0])) / d;
    const ub = ((p2[0] - p1[0]) * (p1[1] - p3[1]) - (p2[1] - p1[1]) * (p1[0] - p3[0])) / d;
    return ua >= 0 && ua <= 1 && ub >= 0 && ub <= 1 ? [p1[0] + ua * (p2[0] - p1[0]), p1[1] + ua * (p2[1] - p1[1])] : null;
  };
  const out = {};
  for (const s of segments) {
    const line = s.centreline;
    for (const w of waterways || []) {
      const c = w.coords || [];
      let at = null;
      for (let i = 1; i < line.length && !at; i++) for (let j = 1; j < c.length && !at; j++) at = hit(line[i - 1], line[i], c[j - 1], c[j]);
      if (at) (out[s.id] = out[s.id] || []).push({ name: w.name || null, kind: w.kind || 'stream', at: [round(at[0], 6), round(at[1], 6)] });
    }
  }
  return out;
}

// Build layer: solar + storage potential outside the exclusion band.
function buildScore(seg, risk10, cfg = DEFAULTS) {
  const m = cfg.money;
  if (seg.irradiance == null || seg.slopePct == null) return { score: null, tier: 'unverified' };
  // Panels go on a narrow strip outside the exclusion band, never the whole study area.
  const stripAcres = cfg.buildStripM == null ? seg.studyAreaAcres
    : Math.min(seg.studyAreaAcres ?? Infinity, ((seg.lengthM || cfg.segmentKm * 1000) * cfg.buildStripM) / 4046.86);
  const usableAcres = seg.slopePct > cfg.buildMaxSlopePct ? 0 : stripAcres;
  const mw = usableAcres / m.acresPerMW;
  const mwhYr = mw * seg.irradiance * 365 * m.performanceRatio;
  const leaseYr = Math.round(usableAcres * m.leaseRatePerAcreYr);
  const partnerYr = Math.round(leaseYr * m.partnerShare);   // shares always add back up to leaseYr
  const sunF = clamp01((seg.irradiance - 2.5) / 2.5);           // 2.5 => 0, 5.0 kWh/m2/day => 1
  const slopeF = 1 - clamp01(seg.slopePct / cfg.buildMaxSlopePct);
  const gridF = seg.substationKm == null ? 0.5 : clamp01(1 - seg.substationKm / 20); // 0 km => 1, 20 km+ => 0
  let score = 100 * (0.45 * sunF + 0.30 * slopeF + 0.25 * gridF);
  if (risk10 && (risk10.tier === 'red' || risk10.tier === 'red-uncertain')) score *= 0.5;
  return {
    score: round(score, 1),
    tier: usableAcres === 0 ? 'excluded' : score >= 60 ? 'green' : score >= 40 ? 'amber' : 'grey',
    usableAcres: round(usableAcres, 1),
    mw: round(mw, 2),
    mwhYr: Math.round(mwhYr),
    leaseYr,
    partnerYr,
    operatorYr: leaseYr - partnerYr,
    avoidedTco2Yr: Math.round(mwhYr * m.gridEmissionFactor),
  };
}

// Money: expected loss and what a work order avoids, over a horizon in years.
function moneyForSegment(risk, years, cfg = DEFAULTS) {
  const m = cfg.money;
  if (!risk || risk.score == null) return null;
  const mult = 0.5 + (m.riskMultiplierMax - 0.5) * (risk.score / 100) ** 2;
  const pFailYr = Math.min(1, m.baseFailRatePerKmYr * mult);
  const pFailHorizon = 1 - (1 - pFailYr) ** years;
  const expectedLoss = pFailHorizon * m.costOfFailure;
  const avoided = expectedLoss * m.mitigationEffectiveness;
  return {
    pFailYr,
    pFailHorizon: round(pFailHorizon, 6),
    expectedLoss: Math.round(expectedLoss),
    avoidedIfFixed: Math.round(avoided),
    netIfFixed: Math.round(avoided - m.workOrderCost),
  };
}

// Work order: what a person approving a segment actually sends to the field.
// Built from the engine's own numbers so the dashboard and n8n produce the same order.
const WO_CHECKS = {
  rain: 'Culverts and ditches: clear and undamaged? Look for erosion gullies crossing the right-of-way.',
  freezeThaw: 'Frost heave: uneven ground, tilted markers or supports, reduced cover over the pipe.',
  saturation: 'Soft or ponded ground, seepage on slopes, sinking along the trench line.',
  vegetation: 'Fresh bare ground or dying vegetation, which can mark slope movement.',
  slope: 'Tension cracks, bulges or scarps upslope of the pipe; leaning trees, posts or fences.',
  crossing: 'River crossing: bank erosion, exposed or undermined pipe, debris against the crossing; measure cover at both banks.',
  wildfire: 'Wildfire: clear dry fuel around valve sites and above-ground equipment; check access roads and firebreaks.',
  drought: 'Drought: desiccation cracks or settlement along the trench line, and dry fuel building up on the right-of-way.',
};
function workOrder(seg, horizonKey = 'y10', cfg = DEFAULTS, opts = {}) {
  const r = (seg.risk && seg.risk[horizonKey]) || {};
  const tier = (seg.override && seg.override.tier) || r.tier || 'unverified';
  const priority = tier === 'red' || tier === 'red-uncertain' ? 'P1' : tier === 'amber' || tier === 'unverified' ? 'P2' : 'P3';
  const now = opts.now ? new Date(opts.now) : new Date();
  const days = (cfg.workOrderDueDays || DEFAULTS.workOrderDueDays)[priority];   // configs saved before this setting existed
  const due = new Date(now.getTime() + days * 86400000);
  const drivers = (r.drivers || []).filter((d) => d.w > 0).slice(0, 3);
  const hz = r.hazards || {};
  // Hazards at medium or above lead the checklist, worst first; then the ground-failure drivers.
  const hzKeys = Object.values(hz).filter((h) => h.key !== 'ground' && h.score >= cfg.tiers.amber).sort((a, b) => b.score - a.score).map((h) => h.key);
  const checks = [...hzKeys.map((k) => WO_CHECKS[k]), ...drivers.map((d) => WO_CHECKS[d.key])].filter(Boolean).slice(0, 5);
  if (!checks.length) checks.push(WO_CHECKS.slope);
  checks.push('Photograph every finding with GPS, and measure depth of cover at the worst spot.');
  const top = drivers[0];
  const why = r.hazard && r.hazard !== 'ground' && hz[r.hazard] ? `${hz[r.hazard].label}: ${hz[r.hazard].why}`
    : top == null ? (tier === 'unverified' ? 'Data missing: confirm conditions on site.' : 'Routine check.')
    : top.key === 'slope' ? `Slope ${top.change}%`
    : top.key === 'vegetation' ? `Plant cover change ${top.change} NDVI over 5 years`
    : `${top.label} ${top.change > 0 ? '+' : ''}${top.change}% vs 1995-2025`;
  const [lon, lat] = seg.mid || (seg.centreline && seg.centreline[0]) || [null, null];
  const ymd = now.toISOString().slice(0, 10).replace(/-/g, '');
  return {
    id: `WO-${seg.id}-${ymd}`,
    segment: seg.id, kmFrom: seg.kmFrom, kmTo: seg.kmTo,
    lat, lon, mapUrl: lat == null ? null : `https://www.google.com/maps?q=${lat},${lon}`,
    priority, dueBy: due.toISOString().slice(0, 10),
    score: r.score ?? null, tier, hazard: r.hazard || 'ground', agreement: r.agreement ?? null, horizon: horizonKey,
    why, checks, estCost: cfg.money.workOrderCost,
    explanation: seg.explanation || null,
    status: 'open', createdAt: now.toISOString(), approvedBy: opts.by || 'operator',
  };
}
// Plain text for email or chat.
function workOrderText(wo) {
  return [
    `${wo.priority} field inspection ${wo.segment} (km ${wo.kmFrom}-${wo.kmTo}), due ${wo.dueBy}`,
    `Risk score ${wo.score ?? '-'} (${wo.tier}), model agreement ${wo.agreement ?? '-'}. Main driver: ${wo.why}`,
    wo.explanation ? `Why: ${wo.explanation}` : null,
    'Check:', ...wo.checks.map((c, i) => `  ${i + 1}. ${c}`),
    wo.mapUrl ? `Location: ${wo.mapUrl}` : null,
    `Work order ${wo.id}, approved by ${wo.approvedBy}. Estimated cost ${wo.estCost}.`,
  ].filter(Boolean).join('\n');
}

// Corridor-level summary: concentration of risk, money headline, top risks.
function corridorSummary(segments, cfg = DEFAULTS, opts = {}) {
  const years = opts.years || 10, topN = opts.topN || 10, key = years <= 5 ? 'y5' : 'y10';
  const rows = segments.map((s) => ({ s, r: s.risk && s.risk[key], money: s.risk && moneyForSegment(s.risk[key], years, cfg), b: s.build }));
  const scored = rows.filter((x) => x.money);
  const totalLoss = scored.reduce((a, x) => a + x.money.expectedLoss, 0);
  const ranked = [...scored].sort((a, b) => b.r.score - a.r.score);
  const top = ranked.slice(0, topN);
  const topLoss = top.reduce((a, x) => a + x.money.expectedLoss, 0);
  const fixable = top.filter((x) => x.r.tier.startsWith('red') || x.r.tier === 'amber');
  const avoided = fixable.reduce((a, x) => a + x.money.avoidedIfFixed, 0);
  const woCost = fixable.length * cfg.money.workOrderCost;
  const kmTotal = segments.reduce((a, s) => a + s.lengthM / 1000, 0);
  // Risk-based inspection: green km are visited every N years instead of yearly.
  const greenKm = rows.filter((x) => x.r && x.r.tier === 'green').reduce((a, x) => a + x.s.lengthM / 1000, 0);
  const inspectionSavingsYr = greenKm * cfg.money.inspectionCostPerKm * (1 - 1 / cfg.money.greenInspectEveryYrs);
  // Only stretches the Build layer marks green count toward lease revenue.
  const buildable = rows.filter((x) => x.b && x.b.tier === 'green');
  const lease = buildable.reduce((a, x) => a + x.b.leaseYr, 0);
  const programCost = cfg.money.programCostYr * years;
  const counts = {};
  for (const x of rows) { const t = (x.r && x.r.tier) || 'unverified'; counts[t] = (counts[t] || 0) + 1; }
  return {
    years,
    segments: segments.length,
    km: round(kmTotal, 1),
    tiers: counts,
    expectedLossTotal: Math.round(totalLoss),
    topShareOfLoss: totalLoss ? round(topLoss / totalLoss, 3) : null,
    workOrders: fixable.length,
    lossAvoided: Math.round(avoided),
    workOrderCost: woCost,
    netAvoided: Math.round(avoided - woCost),
    inspectionSavingsYr: Math.round(inspectionSavingsYr),
    greenKm: round(greenKm, 1),
    buildableKm: round(buildable.reduce((a, x) => a + x.s.lengthM / 1000, 0), 1),
    leaseRevenueYr: Math.round(lease),
    partnerRevenueYr: Math.round(lease * cfg.money.partnerShare),
    mwhYr: buildable.reduce((a, x) => a + x.b.mwhYr, 0),
    mw: round(buildable.reduce((a, x) => a + x.b.mw, 0), 1),
    avoidedTco2Yr: buildable.reduce((a, x) => a + x.b.avoidedTco2Yr, 0),
    programCost,
    // Break-even: failures the program must prevent over the horizon to pay for itself.
    breakEvenFailures: round(programCost / cfg.money.costOfFailure, 2),
    // Years of the program one avoided failure pays for.
    yearsPaidByOneFailure: round(cfg.money.costOfFailure / cfg.money.programCostYr, 1),
    netValue: Math.round(avoided - woCost + inspectionSavingsYr * years - programCost),
    top: top.map((x) => ({ id: x.s.id, score: x.r.score, tier: x.r.tier, agreement: x.r.agreement, driver: x.r.drivers[0],
      hazard: x.r.hazard || 'ground', why: x.r.hazards && x.r.hazards[x.r.hazard] ? x.r.hazards[x.r.hazard].why : null, expectedLoss: x.money.expectedLoss })),
    hazardKm: ['ground', 'crossing', 'wildfire', 'drought'].reduce((o, k) => {
      o[k] = rows.filter((x) => x.r && x.r.hazards && x.r.hazards[k] && x.r.hazards[k].score >= cfg.tiers.red).length; return o; }, {}),
    crossings: rows.filter((x) => x.s.crossings && x.s.crossings.length).length,
  };
}

function mergeConfig(over) {
  const c = JSON.parse(JSON.stringify(DEFAULTS));
  if (!over) return c;
  for (const [k, v] of Object.entries(over)) {
    if (v && typeof v === 'object' && !Array.isArray(v) && c[k] && typeof c[k] === 'object') Object.assign(c[k], v);
    else c[k] = v;
  }
  return c;
}

const ENGINE = { DEFAULTS, mergeConfig, haversine, segmentRoute, quantile, baselineStats, sliceYears, splitModels, projectedStats, ndviTrend, riskScore, findCrossings, peakFlow, buildScore, moneyForSegment, workOrder, workOrderText, corridorSummary };

</script>
<script>
// Where data comes from. When n8n serves this page it sets window.TC_API to its webhook base.
const API = window.TC_API || new URLSearchParams(location.search).get('api') || '';
const DATA_URL = API ? API + '/corridor' : '../data/demo/corridor.json';

// Hex mirrors of the CSS tokens (SVG attributes and Leaflet need literal colours).
const C = { green:'#6fd08f', amber:'#f2a93b', red:'#ff5d4f', 'red-uncertain':'#ff5d4f', unverified:'#5d625a', grey:'#5d625a', excluded:'#3a3e38',
  build:'#d6f35f', buildDim:'#7d8a45', sub:'#82c8ff', ink:'#eceee6', ink2:'#a5aa9f', ink3:'#7a7f75', line:'#252925', line2:'#323732', s1:'#101210', s2:'#161916', bg:'#0a0b0a',
  rain:'#82c8ff', freeze:'#c3b6ff', wet:'#5fd4c4', fire:'#ff8a5c', dry:'#d9b46a', river:'#5aa9ff' };
const HAZ = { ground: 'Ground failure', crossing: 'River crossing', wildfire: 'Wildfire weather', drought: 'Drought' };
const TIER_LABEL = { green:'Low', amber:'Medium', red:'High', 'red-uncertain':'High · models disagree', unverified:'Missing data', grey:'Poor site', excluded:'Too steep' };
const STOPS = ['y0', 'y5', 'y10'];
const STOP_LABEL = { y0:'Today', y5:'2031', y10:'2036' };
const DRIVER_WORD = { rain:'heavy rain', freezeThaw:'freeze-thaw', saturation:'soaked ground', vegetation:'plant loss', slope:'slope' };
const PAGES = ['overview', 'triage', 'segment', 'money', 'build', 'log'];
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;
const ICON_PLAY = '<svg width="14" height="14" viewBox="0 0 14 14"><path d="M3 1.5v11l9.5-5.5z" fill="currentColor"/></svg>';
const ICON_PAUSE = '<svg width="14" height="14" viewBox="0 0 14 14"><rect x="2.5" y="1.5" width="3.2" height="11" rx="1" fill="currentColor"/><rect x="8.3" y="1.5" width="3.2" height="11" rx="1" fill="currentColor"/></svg>';

const $ = (id) => document.getElementById(id);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
const fmt$ = (n) => n == null ? '–' : (n < 0 ? '−' : '') + (Math.abs(n) >= 1e6 ? '$' + (Math.abs(n) / 1e6).toFixed(2) + 'M' : Math.abs(n) >= 1e3 ? '$' + Math.round(Math.abs(n) / 1e3) + 'k' : '$' + Math.round(Math.abs(n)));
const sign = (n) => n == null ? '–' : (n > 0 ? '+' : n < 0 ? '−' : '') + Math.abs(n);
const costFromSlider = (v) => Math.round(430000 * Math.pow(11700000 / 430000, v / 100) / 1000) * 1000;
const sliderFromCost = (c) => Math.round(100 * Math.log(c / 430000) / Math.log(11700000 / 430000));

let D, cfg, segs, page = null, stop = 'y10', layer = 'risk', selected = null, hover = null, filter = 'attn', hazardFilter = 'all', buildFilter = 'ready';
let map, baseLayers = {}, lines = {}, casings = {}, sunBands = {}, sunLayer, crossLayer, crossMarkers = [], annoLayer, audit = [], firstDraw = true, anim = null, playing = false;
const byId = (id) => D.segments.find((s) => s.id === id);
const years = () => stop === 'y5' ? 5 : 10;
const kmOf = (n) => n * ((D.config && D.config.segmentKm) || 1);

/* ---------- config + derived data ---------- */
function readConfig() {
  cfg = ENGINE.mergeConfig({ ...D.config, buildStripM: +sStrip.value, money: { ...D.config.money,
    costOfFailure: costFromSlider(+sCost.value),
    baseFailRatePerKmYr: +sRate.value * 1e-5,
    mitigationEffectiveness: +sEff.value / 100,
    leaseRatePerAcreYr: +sLease.value,
    partnerShare: +sShare.value / 100,
    programCostYr: +sProg.value,
  } });
  vCost.textContent = fmt$(cfg.money.costOfFailure);
  vRate.textContent = cfg.money.baseFailRatePerKmYr.toExponential(1);
  vEff.textContent = Math.round(cfg.money.mitigationEffectiveness * 100) + '%';
  vLease.textContent = '$' + cfg.money.leaseRatePerAcreYr;
  vStrip.textContent = cfg.buildStripM + ' m · ' + ((1000 * cfg.buildStripM) / 4046.86).toFixed(1) + ' ac/km';
  vShare.textContent = Math.round(cfg.money.partnerShare * 100) + '%';
  vProg.textContent = fmt$(cfg.money.programCostYr);
  document.querySelectorAll('input[type=range]').forEach((r) => r.style.setProperty('--p', ((r.value - r.min) / (r.max - r.min)) * 100 + '%'));
}

// "Today": the same engine, with every climate model held at the observed 1995-2025 baseline (no change).
function addObservedStop() {
  for (const s of D.segments) {
    const b = s.baseline;
    if (!b || !s.projections) { s.risk.y0 = ENGINE.riskScore({ ...s, projections: null }, 'y0', cfg); continue; }
    const obs = { extremeDaysPerYr: b.extremeDaysPerYr, refExtremeDaysPerYr: b.extremeDaysPerYr,
      freezeThawDaysPerYr: b.freezeThawDaysPerYr, refFreezeThawDaysPerYr: b.freezeThawDaysPerYr,
      wetSoilDaysPerYr: b.wetSoilDaysPerYr, refWetSoilDaysPerYr: b.wetSoilDaysPerYr,
      drySoilDaysPerYr: b.drySoilDaysPerYr, refDrySoilDaysPerYr: b.drySoilDaysPerYr,
      drySpellDays: b.drySpellDays, refDrySpellDays: b.drySpellDays,
      fireWeatherDaysPerYr: b.fireWeatherDaysPerYr, refFireWeatherDaysPerYr: b.fireWeatherDaysPerYr };
    const r0 = ENGINE.riskScore({ ...s, projections: { y0: { OBSERVED: obs } } }, 'y0', cfg);
    // Today uses no climate models, so "models disagree" can't apply.
    s.risk.y0 = { ...r0, tier: r0.tier === 'red-uncertain' ? 'red' : r0.tier, agreement: 'observed' };
  }
}

function summarize(c = cfg) {
  const k = stop, view = D.segments.map((s) => ({ ...s, risk: { y5: s.risk[k], y10: s.risk[k] } }));
  return ENGINE.corridorSummary(view, c, { years: years(), topN: 10 });
}

// Projected change (%) in a climate driver vs the observed baseline. "Today" is 0 by definition.
function climateAt(s, k) {
  const val = (st) => {
    if (st === 'y0') return s.baseline ? 0 : null;
    const hz = s.risk[st].hazards || {};
    if (k === 'fire') return hz.wildfire ? hz.wildfire.change.fireDays : null;
    if (k === 'drySoil') return hz.drought ? hz.drought.change.drySoil : null;
    const d = (s.risk[st].drivers || []).find((x) => x.key === k); return d ? d.change : null;
  };
  if (!anim) return val(stop);
  const a = val(anim.from), b = val(anim.to);
  if (a == null || b == null) return b ?? a;
  const e = anim.t < .5 ? 2 * anim.t * anim.t : 1 - Math.pow(-2 * anim.t + 2, 2) / 2;
  return a + (b - a) * e;
}
// Corridor mean of a climate driver: observed days/yr and bias-corrected projected days/yr at a stop.
function corridorClimate(k, st = stop) {
  let base = 0, proj = 0, n = 0;
  for (const s of segs) {
    const d = (s.risk.y10.drivers || []).find((x) => x.key === k); if (!d || d.base == null) continue;
    const dp = st === 'y0' ? d : (s.risk[st].drivers || []).find((x) => x.key === k);
    if (!dp || dp.proj == null) continue;
    base += d.base; proj += st === 'y0' ? d.base : dp.proj; n++;
  }
  return n ? { base: base / n, proj: proj / n, change: Math.round((proj / base - 1) * 100), n } : null;
}
// Corridor mean of a hazard measure (fire-weather days, dry-soil days, longest dry spell) at a stop.
function corridorHazard(hk, field, st = stop) {
  let base = 0, proj = 0, n = 0;
  for (const s of segs) {
    const h10 = (s.risk.y10.hazards || {})[hk]; if (!h10 || h10.base[field] == null) continue;
    const hp = st === 'y0' ? h10 : (s.risk[st].hazards || {})[hk];
    const pv = st === 'y0' ? h10.base[field] : hp && hp.proj[field]; if (pv == null) continue;
    base += h10.base[field]; proj += pv; n++;
  }
  return n ? { base: base / n, proj: proj / n, change: Math.round((proj / base - 1) * 100), n } : null;
}
// One short phrase for why a kilometre ranks where it does: its worst hazard.
function whyText(r) {
  const h = r.hazards && r.hazards[r.hazard];
  if (!h || r.hazard === 'ground') return driverText(r.drivers[0]);
  if (r.hazard === 'wildfire') return `wildfire weather ${sign(h.change.fireDays)}%`;
  if (r.hazard === 'drought') return h.change.drySoil != null ? `drought: dry soil ${sign(h.change.drySoil)}%` : 'drought';
  return `river crossing${h.crossings && h.crossings[0] && h.crossings[0].name ? ': ' + h.crossings[0].name : ''}`;
}
function scoreAt(s) {
  if (!anim) return s.risk[stop].score;
  const a = s.risk[anim.from].score, b = s.risk[anim.to].score;
  if (a == null || b == null) return null;
  const e = anim.t < .5 ? 2 * anim.t * anim.t : 1 - Math.pow(-2 * anim.t + 2, 2) / 2;
  return a + (b - a) * e;
}
function tierOf(s) {
  if (s.override && s.override.stop === stop && !anim) return s.override.tier;
  if (!anim) return s.risk[stop].tier || 'unverified';
  const v = scoreAt(s);
  return v == null ? 'unverified' : v >= cfg.tiers.red ? 'red' : v >= cfg.tiers.amber ? 'amber' : 'green';
}
const isHigh = (s) => tierOf(s).startsWith('red');
function mapColor(s) {
  if (layer === 'build') { const t = s.build ? s.build.tier : 'unverified'; return t === 'green' ? C.build : t === 'amber' ? C.buildDim : C[t] || C.grey; }
  return C[tierOf(s)] || C.grey;
}

// Runs of high-risk kilometres (gaps of up to 2 km are bridged), with their main driver.
function clusters() {
  const out = []; let cur = null;
  segs.forEach((s, i) => {
    if (!isHigh(s)) return;
    if (cur && i - cur.to <= 3) cur.to = i; else { cur = { from: i, to: i }; out.push(cur); }
  });
  return out.map((c) => {
    const ss = segs.slice(c.from, c.to + 1).filter(isHigh);
    const counts = {};
    for (const s of ss) { const r = s.risk[stop]; if (r && r.hazard) (counts[r.hazard] = counts[r.hazard] || []).push(s); }
    const [hk, list] = Object.entries(counts).sort((a, b) => b[1].length - a[1].length)[0] || [];
    const all = segs.slice(c.from, c.to + 1);
    // The cluster's label is the hazard most of its high-risk km share, phrased from its worst km.
    const worst = list ? list.reduce((a, x) => (x.risk[stop].score > a.risk[stop].score ? x : a), list[0]) : null;
    return { ...c, n: ss.length, kpFrom: all[0].kmFrom, kpTo: all[all.length - 1].kmTo, mid: all[Math.floor(all.length / 2)], key: hk,
      text: worst ? whyText(worst.risk[stop]) : '' };
  });
}
const kpRange = (c) => `KP ${c.kpFrom}–${c.kpTo}`;
const listJoin = (a) => a.length <= 1 ? a.join('') : a.slice(0, -1).join(', ') + ' and ' + a[a.length - 1];

/* ---------- recompute + refresh ---------- */
function recompute() {
  readConfig();
  for (const s of D.segments) s.build = ENGINE.buildScore(s, s.risk.y10, cfg);
  D.live = summarize();
  refresh();
}
function refresh() {
  paint(); renderLegend(); drawStrip(); updateTimeline(); renderPage(); updateAnnotations();
}
function renderPage() {
  ({ overview: renderOverview, triage: renderTriage, segment: renderSegment, money: renderMoney, build: renderBuild, log: renderLog })[page]();
}

/* ---------- router ---------- */
function parse() {
  const [p, id] = location.hash.replace(/^#\/?/, '').split('/');
  return { p: PAGES.includes(p) ? p : 'overview', id: id || null };
}
const go = (p, id) => { location.hash = '#/' + (p === 'overview' ? '' : p) + (id ? '/' + id : ''); };

function onRoute() {
  const { p, id } = parse();
  const sid = id && byId(id) ? id : null;
  if (p === 'segment' && !sid) return go('triage');
  const prev = page, selPrev = selected;
  page = p;
  selected = ['triage', 'build', 'segment'].includes(p) ? sid : null;
  layer = p === 'build' ? 'build' : 'risk';
  if (prev !== p) {
    for (const v of PAGES) $('view-' + v).hidden = v !== p;
    document.querySelectorAll('#nav a').forEach((a) => a.classList.toggle('on', a.dataset.p === p || (p === 'segment' && a.dataset.p === 'triage')));
    mount();
    $('view-' + p).scrollTop = 0;
  } else if (p === 'segment') $('view-segment').scrollTop = 0;
  refresh();
  if (mapMounted()) {
    if (prev !== p) requestAnimationFrame(() => { map.invalidateSize(); selected ? flyTo(selected, true) : fitAll(); });
    else if (selected && selected !== selPrev) flyTo(selected);
    else if (!selected && selPrev) fitAll(true);
  }
}

function mount() {
  const view = $('view-' + page), ms = view.querySelector('[data-map]'), ss = view.querySelector('[data-strip]');
  (ms || $('parking')).appendChild(mapBox);
  (ss || $('parking')).appendChild(sheet);
  firstDraw = true;
}
const mapMounted = () => mapBox.parentElement && mapBox.parentElement.id !== 'parking';

/* ---------- sun exposure ---------- */
// NASA POWER all-sky irradiance (kWh/m2/day). The ramp is stretched to this corridor's own range,
// and the legend prints the real min and max so the stretch is never hidden.
const SUN_STOPS = [[0, [74, 44, 18]], [.5, [242, 169, 59]], [1, [255, 236, 140]]];
function sunRange() {
  const v = segs.map((s) => s.irradiance).filter((x) => x != null);
  return v.length ? [Math.min(...v), Math.max(...v)] : [0, 1];
}
function sunColor(v) {
  const [lo, hi] = sunRange(), t = hi > lo ? Math.min(1, Math.max(0, (v - lo) / (hi - lo))) : .5;
  const i = t <= .5 ? 0 : 1, a = SUN_STOPS[i], b = SUN_STOPS[i + 1], k = (t - a[0]) / (b[0] - a[0]);
  return 'rgb(' + a[1].map((c, j) => Math.round(c + (b[1][j] - c) * k)).join(',') + ')';
}
const sunGradient = () => `linear-gradient(to right, ${[0, .25, .5, .75, 1].map((t) => { const [lo, hi] = sunRange(); return sunColor(lo + t * (hi - lo)); }).join(',')})`;

/* ---------- map ---------- */
function initMap() {
  // setView now so Leaflet counts as "loaded"; otherwise invalidateSize() is a no-op and the first fit uses a 0x0 size.
  map = L.map('map', { zoomControl: false, zoomSnap: .25, zoomDelta: .5 }).setView([53.1, -112.4], 8);
  L.control.zoom({ position: 'topright' }).addTo(map);
  baseLayers.sat = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { attribution: 'Imagery: Esri, Maxar, Earthstar Geographics', maxZoom: 18 });
  baseLayers.map = L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', { attribution: '© OpenStreetMap contributors © CARTO', subdomains: 'abcd', maxZoom: 19 });
  baseLayers.sat.addTo(map);
  const all = [];
  sunLayer = L.layerGroup();
  for (const s of segs) {
    if (s.irradiance == null) continue;
    sunBands[s.id] = L.polyline(s.centreline.map((p) => [p[1], p[0]]), { color: sunColor(s.irradiance), weight: 30, opacity: .62, lineCap: 'butt', interactive: false }).addTo(sunLayer);
  }
  for (const s of segs) {
    const ll = s.centreline.map((p) => [p[1], p[0]]); all.push(...ll);
    casings[s.id] = L.polyline(ll, { color: C.bg, weight: 9, opacity: .9, interactive: false }).addTo(map);
  }
  for (const s of segs) {
    const ll = s.centreline.map((p) => [p[1], p[0]]);
    lines[s.id] = L.polyline(ll, { color: C.grey, weight: 5, lineCap: 'butt' }).addTo(map)
      .on('click', () => select(s.id)).on('mouseover', () => setHover(s.id)).on('mouseout', () => setHover(null))
      .bindTooltip(() => tipText(s), { sticky: true, className: 'tc', direction: 'top', offset: [0, -10] });
  }
  (D.substations || []).forEach((p) => L.circleMarker([p[1], p[0]], { radius: 5, color: C.bg, weight: 2, fillColor: C.sub, fillOpacity: 1 })
    .addTo(map).bindTooltip('Substation (illustrative)', { className: 'tc' }));
  crossLayer = L.layerGroup().addTo(map);
  for (const s of segs) for (const x of s.crossings || []) {
    if (!x.at) continue;
    crossMarkers.push({ s, m: L.circleMarker([x.at[1], x.at[0]], { radius: 7, color: C.bg, weight: 2, fillColor: C.river, fillOpacity: 1 })
      .addTo(crossLayer).on('click', () => select(s.id))
      .bindTooltip(() => { const h = (s.risk[stop].hazards || {}).crossing; return `<b>River crossing</b> · ${esc(x.name || x.kind)}${x.peakFlowM3s != null ? ' · peak ' + Math.round(x.peakFlowM3s) + ' m³/s' : ''}${h ? ' · ' + TIER_LABEL[h.tier] + ' ' + Math.round(h.score) : ''}`; }, { className: 'tc', direction: 'top', offset: [0, -8] }) });
  }
  annoLayer = L.layerGroup().addTo(map);
  D.bounds = L.latLngBounds(all);
  new ResizeObserver(() => map.invalidateSize()).observe(mapBox);
}
function fitAll(animate) {
  // Overview sits back a little so the corridor reads in its landscape; workspaces fit tighter.
  const pad = page === 'overview' ? D.bounds.pad(.12) : D.bounds;
  map.fitBounds(pad, { paddingTopLeft: [48, 48], paddingBottomRight: [48, 120], animate: !!animate });
}
function cardPad() { return window.innerWidth > 860 && page !== 'overview' ? 440 : 0; }
function flyTo(id, instant) {
  const s = byId(id); if (!s || !mapMounted()) return;
  const b = L.latLngBounds(s.studyPolygon.map((p) => [p[1], p[0]])).pad(1.6);
  const opts = { paddingTopLeft: [40, 40], paddingBottomRight: [cardPad() + 40, 120], maxZoom: 14 };
  if (instant || REDUCED) map.fitBounds(b, { ...opts, animate: false }); else map.flyToBounds(b, { ...opts, duration: .8 });
}
function tipText(s) {
  if (layer === 'build') return `<b>${s.id}</b> · ${TIER_LABEL[s.build.tier] === 'Low' ? 'Build-ready' : s.build.tier === 'green' ? 'Build-ready' : TIER_LABEL[s.build.tier] || s.build.tier}${s.build.mw ? ' · ' + s.build.mw + ' MW' : ''}${s.irradiance != null ? ' · sun ' + s.irradiance.toFixed(2) + ' kWh/m²/day' : ''}`;
  const v = scoreAt(s);
  const r = s.risk[stop];
  return `<b>${s.id}</b> · ${TIER_LABEL[tierOf(s)]} risk · ${v == null ? '–' : v.toFixed(0)}${r && r.hazard ? ' · ' + esc(whyText(r)) : ''}`;
}
function paint() {
  if (!map) return;
  if (layer === 'build' && !map.hasLayer(sunLayer)) { sunLayer.addTo(map); sunLayer.eachLayer((l) => l.bringToBack()); }
  if (layer !== 'build' && map.hasLayer(sunLayer)) map.removeLayer(sunLayer);
  for (const s of segs) {
    const isSel = s.id === selected, isHov = s.id === hover, t = tierOf(s);
    const w = isSel ? 9 : isHov ? 8 : (layer === 'risk' && t.startsWith('red') ? 6.5 : 5);
    lines[s.id].setStyle({ color: mapColor(s), weight: w, opacity: selected && !isSel && !isHov ? .75 : 1 });
    casings[s.id].setStyle({ color: isSel ? C.ink : C.bg, weight: w + (isSel ? 6 : 4) });
    if (isSel || isHov) { casings[s.id].bringToFront(); lines[s.id].bringToFront(); }
  }
  // Crossing markers take the crossing hazard's own colour ring, always on top.
  for (const { s, m } of crossMarkers) {
    const h = (s.risk[anim ? anim.to : stop].hazards || {}).crossing;
    m.setStyle({ color: h ? C[h.tier] : C.bg, weight: 3, fillColor: C.river });
    if (layer === 'risk') m.bringToFront();
  }
  if (crossLayer) { if (layer === 'risk' && !map.hasLayer(crossLayer)) crossLayer.addTo(map); if (layer !== 'risk' && map.hasLayer(crossLayer)) map.removeLayer(crossLayer); }
}
function renderLegend() {
  const rows = layer === 'build'
    ? [['Good site', C.build], ['Possible', C.buildDim], ['Poor site', C.grey], ['Too steep', C.excluded]]
    : [['High · send a crew', C.red], ['Medium · watch', C.amber], ['Low · inspect less', C.green], ['Missing data', null]];
  legend.innerHTML = `<div class="t">${layer === 'build' ? 'Where solar panels fit' : 'Natural-hazard risk · ' + STOP_LABEL[anim ? anim.to : stop]}</div>` +
    rows.map(([l, c]) => `<span class="li"><span class="sw ${c ? '' : 'hatch'}" style="${c ? 'background:' + c : ''}"></span>${l}</span>`).join('') +
    `<span class="li"><span class="sw" style="background:${C.sub};width:8px;height:8px;border-radius:50%;margin:0 4px"></span>Substation</span>` +
    (layer === 'risk' ? `<span class="li"><span class="sw" style="background:${C.river};width:10px;height:10px;border-radius:50%;margin:0 3px;box-shadow:0 0 0 2px ${C.amber}"></span>River crossing (ring = its risk)</span>` : '') +
    (layer === 'build' ? (() => { const [lo, hi] = sunRange(); return `<div class="sun"><div class="t">Sunlight (wide band)</div><span class="ramp" style="background:${sunGradient()}"></span>
      <span class="rl"><span>${lo.toFixed(2)}</span><span>${hi.toFixed(2)} kWh/m²/day</span></span><span class="cap" style="margin:4px 0 0">Brighter = more sun. NASA satellite data, kWh/m² per day. Colours are stretched to this corridor's range.</span></div>`; })() : '');
  timeline.hidden = layer === 'build';
}
function updateAnnotations() {
  if (!annoLayer) return;
  annoLayer.clearLayers();
  if (layer !== 'risk' || anim) return;
  for (const c of clusters()) {
    if (c.n < 2) continue;
    const m = c.mid.mid;
    L.tooltip({ permanent: true, direction: 'right', className: 'anno', offset: [14, 0] })
      .setLatLng([m[1], m[0]]).setContent(`<b>${kpRange(c)}</b>${esc(c.text)}`).addTo(annoLayer);
  }
}

/* ---------- projection timeline ---------- */
function updateTimeline() {
  const pos = { y0: 0, y5: 50, y10: 100 };
  const at = anim ? pos[anim.from] + (pos[anim.to] - pos[anim.from]) * anim.t : pos[stop];
  tlFill.style.width = at + '%';
  const cur = anim ? anim.to : stop;
  document.querySelectorAll('[data-stop]').forEach((b) => {
    b.classList.toggle('on', b.dataset.stop === cur);
    b.classList.toggle('past', pos[b.dataset.stop] <= at);
    b.setAttribute('aria-pressed', b.dataset.stop === cur);
  });
  bPlay.innerHTML = playing ? ICON_PAUSE : ICON_PLAY;
  bPlay.setAttribute('aria-label', playing ? 'Pause' : 'Play the projection');
}
function transitionTo(to, done) {
  if (to === stop) return done && done();
  if (REDUCED) { stop = to; recompute(); return done && done(); }
  anim = { from: stop, to, t: 0 };
  annoLayer && annoLayer.clearLayers();
  const t0 = performance.now(), dur = 1300;
  const step = (now) => {
    if (!anim) return;
    anim.t = Math.min(1, (now - t0) / dur);
    paint(); drawStrip(); updateTimeline();
    if (anim.t < 1) requestAnimationFrame(step);
    else { anim = null; stop = to; recompute(); done && done(); }
  };
  renderLegend();
  requestAnimationFrame(step);
}
function setStop(to) { stopPlay(); if (anim) { anim = null; } transitionTo(to); }
function stopPlay() { playing = false; clearTimeout(play._t); updateTimeline(); }
function play() {
  if (playing) return stopPlay();
  playing = true; updateTimeline();
  const run = () => {
    if (!playing) return;
    const i = STOPS.indexOf(stop);
    if (i === STOPS.length - 1) { stopPlay(); return; }
    transitionTo(STOPS[i + 1], () => { if (playing) play._t = setTimeout(run, 900); });
  };
  if (stop === 'y10') { stop = 'y0'; recompute(); play._t = setTimeout(run, 700); } else run();
}

/* ---------- alignment strip ---------- */
const LANES = [
  { k: 'score', label: 'Risk (0–100)', h: 56 },
  { k: 'tier', label: 'High / med / low', h: 8 },
  { k: 'slope', label: 'Slope', h: 20 },
  { k: 'ndvi', label: 'Plant cover Δ', h: 20 },
  { k: 'build', label: 'Solar MW', h: 20 },
];
// Build strip: sun, capacity and the constraints that limit it.
const BUILD_LANES = [
  { k: 'build', label: 'Solar MW', h: 40 },
  { k: 'sun', label: 'Sunlight', h: 20 },
  { k: 'slope', label: 'Slope', h: 20 },
  { k: 'tier', label: 'Risk by 2036', h: 8, fixed: 'y10' },
];
// Overview strip: climate only.
const CLIMATE_LANES = [
  { k: 'score', label: 'Risk (0–100)', h: 56 },
  { k: 'tier', label: 'High / med / low', h: 8 },
  { k: 'rain', label: 'Heavy rain', h: 28, clim: true, col: C.rain },
  { k: 'freezeThaw', label: 'Freeze-thaw', h: 28, clim: true, col: C.freeze },
  { k: 'saturation', label: 'Soaked ground', h: 28, clim: true, col: C.wet },
