const LW = 92, GAP = 10, RULER = 20;
let G = null;

function drawStrip() {
  const slot = sheet.parentElement;
  if (!slot || slot.id === 'parking' || !strip.clientWidth) return;
  const sc = +slot.dataset.strip || 1, annot = !!slot.dataset.annot && layer === 'risk';
  const W = strip.clientWidth, n = segs.length, top = annot ? 46 : 0;
  const lanes = (slot.dataset.lanes === 'climate' ? CLIMATE_LANES : slot.dataset.lanes === 'build' ? BUILD_LANES : LANES).map((l) => ({ ...l, h: Math.round(l.h * (l.k === 'tier' ? 1 : sc)) }));
  const H = top + lanes.reduce((a, l) => a + l.h, 0) + GAP * (lanes.length - 1) + RULER;
  strip.setAttribute('viewBox', `0 0 ${W} ${H}`); strip.setAttribute('height', H);
  const bw = (W - LW) / n, pad = bw > 4 ? 1 : 0, x = (i) => LW + i * bw;
  const maxMw = Math.max(...segs.map((s) => (s.build && s.build.mw) || 0), 1);
  let y = top, out = `<defs><pattern id="hatch" width="4" height="4" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="1.5" height="4" fill="${C.grey}"/></pattern></defs>`;
  const g = (i) => firstDraw && !REDUCED ? ` class="grow" style="animation-delay:${Math.round(i * 2.5)}ms"` : '';
  let scoreTop = y;
  for (const lane of lanes) {
    const h = lane.h;
    out += `<text x="0" y="${y + Math.min(h, 14) - 2}" fill="${C.ink2}" font-size="11.5">${lane.label}</text>`;
    out += `<rect x="${LW}" y="${y}" width="${W - LW}" height="${h}" fill="${C.s2}" rx="2"/>`;
    if (lane.k === 'score') {
