      for (const t of [cfg.tiers.amber, cfg.tiers.red]) {
        const ty = y + h * (1 - t / 100);
        out += `<line x1="${LW}" x2="${W}" y1="${ty}" y2="${ty}" stroke="${C.line2}" stroke-dasharray="2 3"/><text x="${LW - 6}" y="${ty + 3.5}" fill="${C.ink3}" font-size="9.5" text-anchor="end" font-family="JetBrains Mono, monospace">${t}</text>`;
      }
    }
    segs.forEach((s, i) => {
      const X = x(i), w = Math.max(bw - pad, .6);
      if (lane.k === 'score') {
        const v = scoreAt(s), t = tierOf(s);
        if (v == null) out += `<rect x="${X}" y="${y}" width="${w}" height="${h}" fill="url(#hatch)" opacity=".7"/>`;
        else { const bh = Math.max(1, h * v / 100); out += `<rect${g(i)} x="${X}" y="${y + h - bh}" width="${w}" height="${bh}" fill="${C[t]}"/>`; }
