      } else if (lane.k === 'ndvi') {
        const v = s.ndvi && s.ndvi.change5yr; if (v == null) return;
        const mid = y + h / 2, bh = Math.max(1, (h / 2) * Math.min(1, Math.abs(v) / cfg.ndviDropFull));
        out += `<rect x="${X}" y="${v < 0 ? mid : mid - bh}" width="${w}" height="${bh}" fill="${v < 0 ? C.amber : C.green}" opacity="${v < 0 ? .85 : .55}"/>`;
      } else if (lane.k === 'cross') {
        if (!(s.crossings && s.crossings.length)) return;
        const h = (s.risk[anim ? anim.to : stop].hazards || {}).crossing;
        out += `<rect x="${X - .5}" y="${y}" width="${Math.max(w + 1, 3)}" height="${h ? lane.h : lane.h}" fill="${C.river}" stroke="${h ? C[h.tier] : 'none'}" stroke-width="1.5" rx="1"/>`;
      } else if (lane.k === 'sun') {
        if (s.irradiance == null) { out += `<rect x="${X}" y="${y}" width="${w}" height="${h}" fill="url(#hatch)" opacity=".5"/>`; return; }
        out += `<rect x="${X}" y="${y}" width="${w}" height="${h}" fill="${sunColor(s.irradiance)}"/>`;
      } else if (lane.clim) {
