        if (Math.abs(v) < .5) return;
        const mid = y + h / 2, bh = Math.max(1, (h / 2) * Math.min(1, Math.abs(v) / 100));
        out += `<rect x="${X}" y="${v < 0 ? mid : mid - bh}" width="${w}" height="${bh}" fill="${v < 0 ? C.ink3 : lane.col}" opacity="${v < 0 ? .7 : 1}"/>`;
      } else if (lane.k === 'build') {
        const b = s.build; if (!b || !b.mw) return;
        const bh = Math.max(1, h * b.mw / maxMw);
