    for (const c of clusters()) {
      if (c.n < 2) continue;
      const x0 = x(c.from), x1 = x(c.to + 1), cx = (x0 + x1) / 2, label = `${kpRange(c)}  ${c.text}`, tw = label.length * 6.4;
      const tx = Math.min(Math.max(cx, LW + tw / 2), W - tw / 2);
      const row = tx - tw / 2 > rowEnd[0] + 12 ? 0 : 1;   // second row when labels would collide
      rowEnd[row] = tx + tw / 2;
