      out += `<text x="${tx}" y="${ty}" fill="${C.ink}" font-size="11.5" text-anchor="middle"><tspan font-weight="600" font-family="JetBrains Mono, monospace">${kpRange(c)}</tspan>  ${esc(c.text)}</text>`;
    }
