    out += `<line x1="${X}" x2="${X}" y1="${y + 3}" y2="${y + 7}" stroke="${C.ink3}"/><text x="${X}" y="${y + 18}" fill="${C.ink3}" font-size="10" font-family="JetBrains Mono, monospace" text-anchor="${k === 0 ? 'start' : k >= n - 2 ? 'end' : 'middle'}">${k}</text>`;
  }
