  return `${s.id} scores ${r.score} (${TIER_LABEL[r.tier].toLowerCase()}) by ${STOP_LABEL[stop]}. The biggest driver is ${d.label.toLowerCase()}: ${what}. Model agreement is ${r.agreement}.`;
