    const tier = q('tier').value, reason = q('reason').value.trim();
    q('tier').classList.toggle('bad', !tier); q('reason').classList.toggle('bad', !reason);
    if (!tier || !reason) { q('err').hidden = false; (tier ? q('reason') : q('tier')).focus(); return; }
    const from = s.risk[stop].tier;
