}
// Approve = a real work order: priority and due date from the tier, a checklist from the score's own drivers.
// With n8n connected, n8n rebuilds it from its stored corridor and its copy replaces this one.
function decide(s, v) {
  const k = stop === 'y0' ? 'y10' : stop;
  if (v === 'approved') {
    if (s.wo === 'approved' && s.workOrder && s.workOrder.status !== 'cancelled') return;
    s.wo = 'approved';
    s.workOrder = { ...ENGINE.workOrder(s, k, cfg, { by: 'operator (demo)' }), delivery: API ? 'sending' : 'local' };
    act(s, 'approve_work_order', { stop: k, workOrderId: s.workOrder.id, priority: s.workOrder.priority, dueBy: s.workOrder.dueBy });
    toast(`${s.workOrder.priority} work order for ${s.id} created · due ${fmtDate(s.workOrder.dueBy)}`);
  } else {
    if (s.wo === 'rejected') return;
    s.wo = 'rejected';
    if (s.workOrder) s.workOrder = { ...s.workOrder, status: 'cancelled' };
    act(s, 'reject_work_order', { stop: k, workOrderId: s.workOrder ? s.workOrder.id : null });
    toast(`${s.id}: no crew sent. Logged.`);
  }
  saveLocal(); renderPage(); renderLog();
}
function statusOf(s) {
  if (s.wo === 'approved' && s.workOrder) return `<span class="status ok">${s.workOrder.priority} · due ${fmtDate(s.workOrder.dueBy).replace(/, \d{4}$/, '')}</span>`;
  return s.wo === 'rejected' ? '<span class="status no">Rejected</span>' : '';
}
function toast(msg) {
  const t = $('toast'); t.textContent = msg; t.classList.add('on');
  clearTimeout(toast._t); toast._t = setTimeout(() => t.classList.remove('on'), 3200);
}
// Without n8n, decisions survive a reload in this browser only. With n8n, n8n is the record.
function saveLocal() {
  if (API) return;
  try {
    const decisions = {};
    for (const s of D.segments) if (s.wo || s.override) decisions[s.id] = { wo: s.wo || null, workOrder: s.workOrder || null, override: s.override || null };
    localStorage.setItem('tc-state', JSON.stringify({ decisions, audit: audit.slice(0, 200) }));
  } catch (e) {}
}
function loadSaved() {
  if (API) {
    for (const w of D.workOrders || []) {
      const s = byId(w.segment); if (!s) continue;
      if (w.status === 'rejected') s.wo = 'rejected';
      else { s.wo = w.status === 'cancelled' ? 'rejected' : 'approved'; s.workOrder = { ...w, delivery: 'n8n' }; }
    }
    for (const s of D.segments) if (s.override && !s.override.stop) s.override.stop = 'y10';
    audit = (D.audit || []).filter((a) => a.segment).map((a) => ({ ...a, note: 'stored in n8n' }));
    return;
  }
  try {
    const st = JSON.parse(localStorage.getItem('tc-state') || 'null'); if (!st) return;
    for (const [id, d] of Object.entries(st.decisions || {})) { const s = byId(id); if (s) Object.assign(s, { wo: d.wo || undefined, workOrder: d.workOrder || undefined, override: d.override || undefined }); }
    audit = st.audit || [];
  } catch (e) {}
}
function wireRows(root) {
  root.querySelectorAll('.qrow').forEach((r) => { r.onclick = () => select(r.dataset.id); r.onmouseenter = () => setHover(r.dataset.id); r.onmouseleave = () => setHover(null); });
