function stopSeg() {
  return `<div class="seg" role="group" aria-label="Projection">${STOPS.map((k) => `<button data-stop="${k}" class="${k === stop ? 'on' : ''}">${STOP_LABEL[k]}</button>`).join('')}</div>`;
}

/* ---------- pages ---------- */
function tween(el, to, fmt) {
  const from = el._v ?? to; el._v = to;
  if (REDUCED || from === to) { el.textContent = fmt(to); return; }
  const t0 = performance.now(), dur = 420;
  cancelAnimationFrame(el._raf);
  const step = (t) => { const k = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - k, 3); el.textContent = fmt(from + (to - from) * e); if (k < 1) el._raf = requestAnimationFrame(step); };
  el._raf = requestAnimationFrame(step);
}
const HELP = {
  risk: 'Each km gets four 0-100 scores: ground failure, river crossing, wildfire weather and drought. Its level is its worst one. 65+ is high, 40-65 medium.',
  fire: 'Days a year with no rain, at least 25 °C and humidity at or below 35%: weather that lets wildfire spread. Fire threatens valve sites and leaves burn scars that slide.',
  drought: 'Days a year the topsoil is drier than the driest 10% of 1995-2025. Drying clay cracks and settles along the trench, and dry land burns.',
  crossing: 'Places where the pipe crosses a river, stream or canal. Bigger rivers, higher peak flow and more heavy rain mean more scour at the crossing.',
  rain: 'Days a year with rain heavy enough to trigger washouts and landslides (the wettest 5% of days in 1995-2025).',
  freezeThaw: 'Days the ground freezes overnight and thaws by day. Repeated cycles loosen soil and heave pipe supports.',
  saturation: 'Days the topsoil is close to fully soaked. Soaked slopes slide more easily.',
  agree: 'We use three independent climate models. When all three point the same way, the projection is more trustworthy.',
  hot: 'The longest run of high-risk kilometres. Click to open it in Triage.',
};
